import tracemalloc

from emu.metrics import MetricsCalculator


class MemoryTracker:
    """
    Tracks memory allocations within the sandbox using Python's built-in tracemalloc.
    Produces a memory timeline for statistical analysis (p50/p95/p99/volatility).
    """
    def __init__(self, limit_mb=512):
        self.limit_bytes = limit_mb * 1024 * 1024
        self.peak_memory = 0
        self.current_memory = 0
        self.timeline = []  # Memory samples (MB) over time

    def start(self):
        tracemalloc.start()

    def check_limit(self):
        """
        Called periodically (e.g. by AST hooks via EmulationState.increment).
        Records a memory sample and enforces the limit.
        """
        if not tracemalloc.is_tracing():
            return

        current, peak = tracemalloc.get_traced_memory()
        self.current_memory = current
        if peak > self.peak_memory:
            self.peak_memory = peak

        # Record timeline sample
        self.timeline.append(current / 1024 / 1024)

        if current > self.limit_bytes:
            tracemalloc.stop()
            raise MemoryError(
                f"Virtual memory limit exceeded! "
                f"Used {current/1024/1024:.2f}MB, Limit {self.limit_bytes/1024/1024:.2f}MB"
            )

    def stop(self):
        if tracemalloc.is_tracing():
            current, peak = tracemalloc.get_traced_memory()
            if peak > self.peak_memory:
                self.peak_memory = peak
            tracemalloc.stop()

    def get_peak_mb(self):
        return self.peak_memory / 1024 / 1024

    def get_memory_profile(self) -> dict:
        """
        Compute the full memory distribution profile from the timeline.
        Returns p50, p95, p99, std_dev, max_spike.
        """
        if not self.timeline:
            return {
                'p50_mb': 0.0, 'p95_mb': 0.0, 'p99_mb': 0.0,
                'volatility': 0.0, 'max_spike': 0.0
            }
        mc = MetricsCalculator
        return {
            'p50_mb': mc.percentile(self.timeline, 50),
            'p95_mb': mc.percentile(self.timeline, 95),
            'p99_mb': mc.percentile(self.timeline, 99),
            'volatility': mc.std_dev(self.timeline),
            'max_spike': mc.curve_max_spike(self.timeline),
        }

